import React from "react";

const CTA = () => {
    return (
        <section className="px-8 py-16 bg-blue-600 text-white text-center">
            <h2 className="text-3xl font-bold">
                Start Managing Water Smarter 💧
            </h2>

            <p className="mt-2">
                Join communities already optimizing water usage.
            </p>

            <button className="mt-6 bg-white text-blue-600 px-6 py-3 rounded-lg">
                Get Started
            </button>
        </section>
    );
};

export default CTA;
